-- Phonics · Vowels section (Nov 13). Run only after the Vowels private files are uploaded. Existing products are preserved.
-- The first three sheets are free; sheets 4 to 10 cost Rs 19. Every sheet has two pages: the sheet, then its answers.
on conflict (id) do nothing;
-- the Vowels card on the Phonics board (there since Nov 3; this only makes sure it shows)
update public.sections set visible = true, group_id = 'phon', group_label = 'Phonics', updated_at = now() where id = 'vowels';
-- check: should list pv-1 to pv-10, the first three with price 0
select id, price_inr, status from public.products where id like 'pv-%' order by sort;
